395→    const limits = PLAN_LIMITS[subscription.planTier];
396→
397→    if (type === "blocked" && !limits.allowBlocked) {
398→      return { error: "Blocked zip codes require a Pro plan or higher." };
399→    }
400→
401→    const currentCount = await db.zipCode.count({ where: { shop } });
402→    if (limits.maxZipCodes !== Infinity && currentCount + rangeSize > limits.maxZipCodes) {
403→      return { error: `This range would exceed your plan limit of ${limits.maxZipCodes} zip codes. You have ${limits.maxZipCodes - currentCount} slots remaining.` };
404→    }
405→
406→    // Generate and upsert all zips in range
407→    let imported = 0;
408→    for (let i = start; i <= end; i++) {
409→      const zipCode = String(i).padStart(5, "0");
410→      try {
411→        await db.zipCode.upsert({
412→          where: { shop_zipCode: { shop, zipCode } },
413→          create: { shop, zipCode, zone: zone ?? undefined, type, message: message ?? undefined, eta: eta ?? undefined },
414→          update: { zone: zone ?? undefined, type, message: message ?? undefined, eta: eta ?? undefined },
415→        });
416→        imported++;
417→      } catch {
418→        // skip individual errors
419→      }
420→    }
421→
422→    return { success: true, action: "range-import", imported, total: rangeSize };
423→  }
424→
425→  return null;
426→};
